def collect(x, buf=None):
    if buf is None:
        buf = []
    buf.append(x)
    return buf

def reverse_str(s):
    return s[::-1]

if __name__ == '__main__':
    print(reverse_str('cat'))

def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

if __name__ == '__main__':
    print(binary_search([-1, 0, 3, 5, 9, 12], 9))

def rotate(nums, k):
    n = len(nums)
    if n == 0:
        return nums
    k %= n
    return nums[-k:] + nums[:-k]

if __name__ == '__main__':
    print(rotate([1, 2, 3, 4, 5], 2))
